import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {cookies} identical cookies are to be shared among n guests under these rules: (i) each cookie is either left whole or cut into exactly two equal halves; (ii) every guest must receive exactly the same total amount of cookie; (iii) every guest must receive exactly {pieces_per_guest} pieces in total (counting a whole cookie as one piece and each half as one piece). Determine the sum of all positive integers n for which such a distribution is possible.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Build M = 2^a * 3^b * 5^c with moderate exponents to keep 2M within ~1e11
# and guarantee a rich divisor structure.
def make_M():
    a = rng.randint(8, 12)
    b = rng.randint(5, 8)
    c = rng.randint(4, 6)
    M = (2 ** a) * (3 ** b) * (5 ** c)
    return M, a, b, c
def divisors_of_2M_from_exponents(a, b, c):
    # 2M = 2^(a+1) * 3^b * 5^c
    divs = []
    for i in range(a + 2):
        pow2 = 2 ** i
        for j in range(b + 1):
            pow3 = 3 ** j
            for k in range(c + 1):
                pow5 = 5 ** k
                divs.append(pow2 * pow3 * pow5)
    return divs
attempts = 0
while True:
    attempts += 1
    M, a, b, c = make_M()
    D = divisors_of_2M_from_exponents(a, b, c)
    # pick a divisor d to guarantee existence in the interval
    rng.shuffle(D)
    ok = False
    # Try multiple choices to ensure non-trivial instance (at least 3 valid n)
    for d in D:
        # n must be positive; d >= 1 always
        low = (M + d - 1) // d  # ceil(M/d)
        high = (2 * M) // d     # floor(2M/d)
        if low <= high:
            # choose p in [low, high]
            p = rng.randint(low, high)
            # compute valid n set size for this p
            low2 = (M + p - 1) // p  # ceil(M/p)
            high2 = (2 * M) // p     # floor(2M/p)
            # valid n are divisors of 2M within [low2, high2]
            S = [x for x in D if low2 <= x <= high2]
            if len(S) >= 3:
                # found a sufficiently non-trivial instance
                return {'cookies': M, 'pieces_per_guest': p}
    # Retry with a new M if we couldn't find a good p
    if attempts > 20:
        # Relax requirement and accept any with at least 1 valid n
        for d in D:
            low = (M + d - 1) // d
            high = (2 * M) // d
            if low <= high:
                p = rng.randint(low, high)
                return {'cookies': M, 'pieces_per_guest': p}

    def verifier(assign):
# Verify the instance and compute the answer.
# The characterization proved in notes: valid n are exactly those with
# n | 2M and ceil(M/p) <= n <= floor(2M/p).
try:
    M = int(assign.get('cookies'))
    p = int(assign.get('pieces_per_guest'))
except Exception:
    return (False, None)  # invalid types
if M <= 0 or p <= 0:
    return (False, None)  # invalid domain
# Compute divisors of 2M efficiently.
N = 2 * M
# Factor N using trial division by small primes, then continue if needed.
fac = {}
x = N
for prime in [2, 3, 5]:
    cnt = 0
    while x % prime == 0:
        x //= prime
        cnt += 1
    if cnt:
        fac[prime] = cnt
# If remainder x > 1, it is a product of primes. We can factor further by trial division
