d = 7
while d * d <= x:
    cnt = 0
    while x % d == 0:
        x //= d
        cnt += 1
    if cnt:
        fac[d] = cnt
    d += 2
if x > 1:
    fac[x] = fac.get(x, 0) + 1
# Generate divisors from prime factorization fac
divs = [1]
for prime, exp in fac.items():
    new_divs = []
    powp = 1
    for _ in range(exp + 1):
        for v in divs:
            new_divs.append(v * powp)
        powp *= prime
    divs = new_divs
# Bounds
low = (M + p - 1) // p
high = (2 * M) // p
if low > high:
    # No n can satisfy; instance degenerate
    return (False, None)
# Valid n are divisors of 2M in [low, high]
valid_ns = [n for n in divs if low <= n <= high]
if len(valid_ns) == 0:
    # Degenerate (should not happen with our generator)
    return (False, None)
ans = sum(valid_ns)
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

